const integrationShowPage=showPage,projectDetailView=detail;
const roleDrafts=[
 {id:'at-head',name:'AT 담당장',scope:'소관 AT 전체',view:'소관 전체',edit:'변경 검토·승인',report:'조회·검토',people:'PO 지정·변경',admin:'없음',description:'소관 조직의 전체 현황과 과제별 분석을 확인하고 목표 계획을 관리합니다.'},
 {id:'team-lead',name:'팀장',scope:'소속 팀 과제',view:'소속 팀',edit:'팀 과제 변경 검토·승인',report:'조회·검토',people:'팀 내 PO·PM 지정',admin:'없음',description:'조직도상 소속 팀의 과제를 관리합니다. 다른 팀에 대한 권한은 별도로 부여합니다.'},
 {id:'system-admin',name:'과제 관리시스템 관리자',scope:'시스템 전체',view:'전체',edit:'전체',report:'정정 권한',people:'전체 담당자 관리',admin:'역할·정책 관리',description:'전체 운영 설정과 권한을 관리합니다. 데이터 정정과 권한 변경은 변경 이력으로 남깁니다.'},
 {id:'project-owner',name:'과제 대표자',scope:'본인이 PO인 과제',view:'본인 과제',edit:'본인 과제',report:'조회·검토',people:'PM·공동 수행자 지정',admin:'없음',description:'과제 PO입니다. 본인이 대표하는 과제의 정보와 목표, 참여 구성을 관리합니다.'},
 {id:'project-participant',name:'과제 참여자',scope:'참여 중인 과제',view:'참여 과제',edit:'PM만 수정',report:'PM·공동 수행자 입력',people:'없음',admin:'없음',description:'PM과 공동 수행자를 포함합니다. PM은 계획과 실적을, 공동 수행자는 실적과 지연 사유·만회 계획을 작성합니다.'},
 {id:'general-member',name:'일반 AT 구성원',scope:'조회가 허용된 과제',view:'허용 범위',edit:'없음',report:'조회만',people:'없음',admin:'없음',description:'조회가 허용된 과제의 내용과 요약을 확인합니다. 참여자로 지정되면 해당 과제의 추가 권한을 갖습니다.'}
];
document.querySelector('#performanceNav').insertAdjacentHTML('afterend','<div id="governanceNav" class="dashnav" role="button" tabindex="0" onclick="showPage(\'governance\')" onkeydown="if(event.key===\'Enter\')showPage(\'governance\')">⚙ &nbsp;권한·연동</div>');
document.querySelector('#listPage .banner').insertAdjacentHTML('beforebegin','<div class="integration-utility"><span>사내 연동 준비</span><button class="text-button" onclick="showPage(\'governance\')">권한·연동 보기</button></div>');
document.querySelector('#performancePage').insertAdjacentHTML('afterend','<main id="governancePage" class="main" hidden></main><main id="projectAiPage" class="main" hidden></main>');
showPage=function(page){document.querySelector('#governancePage').hidden=page!=='governance';document.querySelector('#projectAiPage').hidden=page!=='project-ai';document.querySelector('#governanceNav').classList.toggle('selected',page==='governance');integrationShowPage(page);if(page==='governance')renderGovernance()};
function renderGovernance(){document.querySelector('#governancePage').innerHTML=`<div class="top"><div><div class="eyebrow">IDENTITY & ACCESS</div><h1>권한·연동</h1><p>조직 역할과 과제 내 역할을 함께 적용하는 권한 구성안입니다.</p></div><button class="secondary" onclick="showPage('list')">전체 과제 보기</button></div><div class="integration-notice"><strong>설계 검토 화면 · 실제 권한 제한은 연동 전입니다.</strong><p>현재 시연 데이터는 브라우저에 저장됩니다. 아래 권한표는 사내 SSO·조직도·서버 연동 후 적용할 제안입니다.</p></div><div class="integration-status-grid"><section class="integration-status"><span class="section-kicker">SSO</span><h2>사내 로그인</h2><span class="connection-badge">연동 전</span><p>SSO 계정과 조직도 정보를 연결해 사용자와 소속을 확인합니다.</p></section><section class="integration-status"><span class="section-kicker">AUTHORIZATION</span><h2>과제 수정 권한</h2><span class="connection-badge">정책 검토</span><p>조직 역할에 과제별 PO·PM·공동 수행자 관계를 더해 권한 범위를 결정합니다.</p></section><section class="integration-status"><span class="section-kicker">AI SUMMARY</span><h2>사내 AI</h2><span class="connection-badge">연동 전</span><p>전체·과제별 요약에 동일한 조회 권한을 적용하도록 구성합니다.</p></section></div><section class="panel"><div class="panelhead"><div><h2>역할별 권한 제안</h2><p class="integration-help">‘담당’은 AT 담당장으로 반영했습니다. 과제 대표자는 PO, 과제 참여자는 PM·공동 수행자로 구분합니다.</p></div><span class="draft-badge">검토안</span></div><div class="access-table-wrap"><table class="access-table"><thead><tr><th>역할</th><th>적용 범위</th><th>과제·요약 조회</th><th>정보·목표 변경</th><th>실적 관리</th><th>담당자 지정</th><th>시스템 권한</th></tr></thead><tbody>${roleDrafts.map(r=>`<tr><th scope="row">${r.name}</th><td>${r.scope}</td><td>${r.view}</td><td>${r.edit}</td><td>${r.report}</td><td>${r.people}</td><td>${r.admin}</td></tr>`).join('')}</tbody></table></div><p class="integration-help">여러 역할을 가진 경우 허용 범위를 합쳐 적용하며, 과제별 열람 제한을 우선 확인합니다. 권한이 없는 과제의 AI 요약도 조회할 수 없도록 설계합니다.</p></section><section class="panel"><h2>역할 상세</h2><div class="role-explainer"><div class="field"><label for="policyRole">확인할 역할</label><select id="policyRole" onchange="explainRole(this.value)">${roleDrafts.map(r=>`<option value="${r.id}">${r.name}</option>`).join('')}</select><p class="integration-help">선택은 설명을 확인하기 위한 것으로, 실제 계정 권한을 바꾸지 않습니다.</p></div><div id="roleExplanation" class="role-explanation" aria-live="polite"></div></div></section><section class="panel"><h2>사내 연동 시 적용할 흐름</h2><ol class="identity-flow"><li><strong>로그인</strong><span>사내 SSO로 사용자를 확인</span></li><li><strong>조직 확인</strong><span>조직도에서 소속·직책·재직 상태 확인</span></li><li><strong>과제 관계 확인</strong><span>고유 계정 ID로 PO·PM·공동 수행자 연결</span></li><li><strong>작업 권한 확인</strong><span>서버에서 조회·저장 요청마다 검증</span></li><li><strong>변경 이력</strong><span>변경자·시각·변경 전후 기록</span></li></ol></section><section class="panel integration-next"><h2>실제 연결에 필요한 정보</h2><ul><li>사내 SSO 시스템과 지원 방식, 조직도 조회 담당 부서</li><li>사내 AI 서비스의 연결 방식과 사용 가능한 모델</li><li>역할별 권한표와 데이터 열람 범위 확정</li></ul><p>연결 정보가 확인되면 화면뿐 아니라 데이터 저장과 권한 검증도 서버에 적용해야 합니다.</p></section>`;explainRole(roleDrafts[0].id)}
function explainRole(id){const r=roleDrafts.find(x=>x.id===id);if(!r)return;document.querySelector('#roleExplanation').innerHTML=`<span class="scope-label">${r.scope}</span><h3>${r.name}</h3><p>${r.description}</p>`}
let projectAiId='',projectAiReturn='list';
function evidenceCards(items,empty){return items.length?items.map(i=>`<div class="insight-evidence"><p>${esc(i.text)}</p><small>근거 · ${esc(Array.isArray(i.evidence)?i.evidence.join(' / '):i.evidence)}</small></div>`).join(''):`<p class="insight-empty">${esc(empty)}</p>`}
function openProjectSummary(id){const x=data.find(a=>a.id===id);if(!x)return;if(!document.querySelector('#projectAiPage').hidden){projectAiId=id}else{projectAiReturn=!document.querySelector('#dashboardPage').hidden?'dashboard':'list';projectAiId=id}closeModal();showPage('project-ai');renderProjectSummary()}
function renderProjectSummary(){const x=data.find(a=>a.id===projectAiId);if(!x){showPage('list');return}const s=ProjectInsights.build(x);document.querySelector('#projectAiPage').innerHTML=`<div class="summary-breadcrumb"><button class="text-button" onclick="backFromSummary()">과제 상세로 돌아가기</button><button class="text-button" onclick="showPage('governance')">권한·연동</button></div><div class="top"><div><div class="eyebrow">PROJECT AI SUMMARY</div><h1>${esc(x.title)}</h1><p>${esc(x.team||'팀 미지정')} · PO ${esc(x.po||'미지정')} · PM ${esc(x.pm||'미지정')}</p></div><button class="secondary" onclick="renderProjectSummary();toast('최신 입력 데이터로 분석을 갱신했습니다.')">입력 데이터 다시 분석</button></div><div class="integration-notice"><strong>사내 AI 연동 전 · 현재는 입력 데이터에 기반한 규칙 분석입니다.</strong><p>과제의 요약·강점·취약점·개선 방향을 아래와 같이 확인할 수 있습니다. 내용의 품질을 평가하는 AI 분석은 연결 후 제공됩니다.</p></div><section class="summary-overview"><div class="summary-panel-head"><h2>과제 요약</h2><span class="draft-badge">규칙 기반</span></div><p>${esc(s.overview)}</p><div class="summary-sources"><span>분석 기준 ${esc(s.coverage.asOf||monthNow())}</span><span>${esc(s.coverage.reportedMonths??0)} / ${esc(s.coverage.dueMonths??0)}개월 실적 입력</span><span>입력 데이터 기준 · 저장된 AI 결과 없음</span></div></section><div class="project-summary-grid"><section class="summary-block strength"><span class="section-kicker">STRENGTHS</span><h2>확인된 강점</h2>${evidenceCards(s.strengths,'입력 데이터에서 확인할 수 있는 강점이 아직 없습니다.')}</section><section class="summary-block risk"><span class="section-kicker">RISKS</span><h2>취약점 및 확인 사항</h2>${evidenceCards(s.risks,'현재 입력 데이터에서 확인된 항목이 없습니다.')}</section><section class="summary-block improve"><span class="section-kicker">IMPROVEMENTS</span><h2>개선 방향</h2>${evidenceCards(s.improvements,'추가 입력 데이터가 쌓이면 개선할 항목을 다시 확인해 주세요.')}</section></div><section class="panel"><h2>분석에 사용한 데이터</h2><div class="source-tags">${s.sources.map(a=>`<span>${esc(a)}</span>`).join('')}</div><p class="integration-help">관찰 내용마다 근거를 표시합니다. 입력이 없거나 확인할 수 없는 내용은 판단을 보류합니다.</p></section><section class="panel summary-connection"><div><h2>사내 AI 연결 후</h2><p>과제 맥락을 반영한 요약과 개선 제안을 생성하고, 생성 시점·분석 대상 월·근거를 함께 표시합니다. 과제 조회 권한과 동일한 접근 범위를 적용합니다.</p></div><span class="connection-badge">연동 전</span></section><div class="summary-actions"><button class="secondary" onclick="openSummaryPerformance()">월별 실적 확인</button><button class="primary" onclick="openSummaryEdit()">과제·목표 수정</button></div>`}
function backFromSummary(){showPage(projectAiReturn);detail(projectAiId)}
function openSummaryPerformance(){openPerformance(projectAiId)}
function openSummaryEdit(){openForm(projectAiId)}
detail=function(id){projectDetailView(id);const x=data.find(a=>a.id===id),s=ProjectInsights.build(x),preview=document.createElement('section');preview.className='project-summary-preview';preview.innerHTML=`<div><div class="section-kicker">PROJECT AI SUMMARY</div><h3>과제별 요약 및 인사이트</h3><p>${esc(s.overview)}</p><span>규칙 기반 분석 · 사내 AI 연동 전</span></div><button type="button" class="secondary">AI Summary 보기</button>`;preview.querySelector('button').onclick=()=>openProjectSummary(id);document.querySelector('#dialog .dialoghead').after(preview)};
